 for i in missing:
  n=t['original_viewpoint_path'][i];key=(t['scene'],n);source=identity[key];g=geometry.get(key);refs.append({'reference_index':i,'node':n,'identity_method':source['method'],'no_potential_support_in_checked_region':g['no_potential_support_inside_allowed_region'] if g else None,'geometry_checked':g is not None});nodes[key].append(t['task_key'])
 rows.append({'task_key':t['task_key'],'scene':t['scene'],'path_id':t['path_id'],'source_record_sha256':t['source_record_sha256'],'official_episode_matched':match,'reason':kind,'missing_reference_points':refs,'candidate_component_counts':l['candidate_component_counts']})
